// GENERATED by scripts/sync-shared.mjs from app/src/points/rewards.ts. Do not edit here.
// PRD P12 fee splits and user reward balances (P12.4). All shares apply to the NET fee,
// i.e. what reaches Potswap's referral accounts after Jupiter's 20%.
export const JUPITER_SHARE = 0.2

export interface FeeSplit { launchPool: number; rewardBalances: number; burn: number; team: number }

/** Season 0 (pre-launch): 60% pool / 20% reward balances / 20% team. Seasons 1+: 30% burn / 20% reward / 50% team. */
export function splitFor(season: number): FeeSplit {
  return season === 0
    ? { launchPool: 0.6, rewardBalances: 0.2, burn: 0, team: 0.2 }
    : { launchPool: 0, rewardBalances: 0.2, burn: 0.3, team: 0.5 }
}

export const REWARD_SHARE = 0.2

export interface SplitAmounts extends FeeSplit { net: number }

export function splitAmounts(netFee: number, season: number): SplitAmounts {
  const s = splitFor(season)
  return { net: netFee, launchPool: netFee * s.launchPool, rewardBalances: netFee * s.rewardBalances, burn: netFee * s.burn, team: netFee * s.team }
}

/** Reward balance credit for one swap, in SOL: 20% of the net fee at the SOL price of the moment. */
export function rewardSolFor(feeUsd: number, solPriceUsd: number): number | null {
  if (!(feeUsd >= 0) || !(solPriceUsd > 0)) return null
  return (feeUsd * REWARD_SHARE) / solPriceUsd
}

export interface RewardLedger { creditedSol: number; claimedSol: number }
export const rewardBalanceSol = (l: RewardLedger) => Math.max(0, l.creditedSol - l.claimedSol)

/** Gross → net helper for displays that start from the referral fee charged. */
export const netOfGross = (grossUsd: number) => grossUsd * (1 - JUPITER_SHARE)
